with open('Aurelian/app/src/main/java/com/aurelian/app/MainFeedScreen.kt', 'r') as f:
    content = f.read()
old = '        // Background Placeholder (Cover Image)\n        AsyncImage(\n            model = user.videoUrl, \n            contentDescription = "Cover Image",\n            contentScale = ContentScale.Crop,\n            modifier = Modifier.fillMaxSize()\n        )\n\n        // Video Player Background with Fade-in Animation\n        AnimatedVisibility(\n            visible = isVideoReady,\n            enter = fadeIn(animationSpec = tween(700)),\n            exit = fadeOut()\n        ) {\n            exoPlayer?.let { player ->\n                AndroidView(\n                    factory = { ctx ->\n                        PlayerView(ctx).apply {\n                            this.player = player\n                            useController = false\n                            resizeMode = AspectRatioFrameLayout.RESIZE_MODE_ZOOM\n                            layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)\n                        }\n                    },\n                    modifier = Modifier.fillMaxSize(),\n                    update = { view ->\n                        view.player = player\n                    }\n                )\n            }\n        }'
new_rep = '        // Base Layer: Video Player\n        exoPlayer?.let { player ->\n            AndroidView(\n                factory = { ctx ->\n                    PlayerView(ctx).apply {\n                        this.player = player\n                        useController = false\n                        resizeMode = AspectRatioFrameLayout.RESIZE_MODE_ZOOM\n                        layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)\n                        val videoSurfaceView = this.videoSurfaceView\n                        if (videoSurfaceView is android.view.SurfaceView) {\n                            videoSurfaceView.setZOrderMediaOverlay(false)\n                        }\n                    }\n                },\n                modifier = Modifier.fillMaxSize(),\n                update = { view ->\n                    view.player = player\n                }\n            )\n        }\n\n        // Overlay Layer 1: Cover Image Placeholder\n        AnimatedVisibility(\n            visible = !isVideoReady,\n            enter = fadeIn(),\n            exit = fadeOut(animationSpec = tween(700))\n        ) {\n            AsyncImage(\n                model = user.videoUrl, \n                contentDescription = "Cover Image",\n                contentScale = ContentScale.Crop,\n                modifier = Modifier.fillMaxSize().background(DeepBlack)\n            )\n        }'
content = content.replace(old, new_rep)
with open('Aurelian/app/src/main/java/com/aurelian/app/MainFeedScreen.kt', 'w') as f:
    f.write(content)
